                additionalProperties: false,
                // labels is a map of string -> string values; allow arbitrary
                // string keys but enforce string values.
              }
            }
          }
        }
      }
    }
  ];
}

const VALID_STRING_TYPE = (v) => typeof v === 'string';

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function normalizeProfile(profile) {
  if (!isPlainObject(profile)) {
    throw new Error('profile must be an object');
  }

  const allowed = ['name', 'labels'];
  for (const key of Object.keys(profile)) {
    if (!allowed.includes(key)) {
      throw new Error(`Unknown field in profile: ${key}`);
    }
  }

  const normalized = {};

  if (profile.name !== undefined) {
    if (!VALID_STRING_TYPE(profile.name)) {
      throw new Error('profile.name must be a string');
    }
    normalized.name = profile.name;
  }

  if (profile.labels !== undefined) {
    if (!isPlainObject(profile.labels)) {
      throw new Error('profile.labels must be an object');
    }
    const normalizedLabels = {};
    for (const [key, value] of Object.entries(profile.labels)) {
      if (!VALID_STRING_TYPE(value)) {
        throw new Error(`profile.labels.${key} must be a string`);
      }
      normalizedLabels[key] = value;
    }
    normalized.labels = normalizedLabels;
  }

  return normalized;
}

export async function callTool(name, args = {}) {
  if (name !== 'profile_patch') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }

  if (!isPlainObject(args)) {
    const err = new Error('arguments must be an object');
    err.code = -32602;
    throw err;
  }

  const allowedArgs = ['profile'];
  for (const key of Object.keys(args)) {
    if (!allowedArgs.includes(key)) {
      const err = new Error(`Unknown argument: ${key}`);
      err.code = -32602;
      throw err;
    }
  }

  if (args.profile === undefined) {
    const err = new Error('profile is required');
    err.code = -32602;
    throw err;
  }

  const normalized = normalizeProfile(args.profile);

  return {
    content: [{ type: 'text', text: JSON.stringify(normalized) }]
  };
}

